import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-08-27","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-08-27","date":"2025-08-27T00:00:00.000Z","updated":"2025-09-08T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","稳定性","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-08-27.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-08-27.md","lastUpdated":1780460162000}'),l={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-08-27.md"};function r(n,e,s,g,p,d){return t(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>本次会议主要讨论了Ceph RGW的重构问题，包括Usage Log Trimming问题、RGW测试套件稳定性问题以及RGW主要版本稳定性策略。</p><h3 id="_1-usage-log-trimming问题讨论" tabindex="-1">1. Usage Log Trimming问题讨论 <a class="header-anchor" href="#_1-usage-log-trimming问题讨论" aria-label="Permalink to &quot;1. Usage Log Trimming问题讨论&quot;">​</a></h3><p><strong>问题描述</strong>：当前Ceph RGW的Usage Log管理方式存在两种key格式，但实际操作中出现key格式混合存储的情况，导致trim操作无法正确清理过期logs，影响性能。</p><p><strong>解决方案提案</strong>：提出两种解决方案：</p><ul><li><strong>方案1</strong>：修改key格式，确保与time-based key严格分离。</li><li><strong>方案2</strong>：调整迭代逻辑，兼容混合key场景。</li></ul><p><strong>讨论要点</strong>：</p><ul><li>方案1需通过config option控制过渡逻辑，未来可关闭以消除性能开销。</li><li>仅影响cls_rgw.cc，对用户透明。</li></ul><p><strong>后续行动</strong>：</p><ul><li>提交PR供团队审核。</li><li>完善Release Notes，说明配置选项的调整步骤。</li></ul><h3 id="_2-rgw测试套件稳定性问题" tabindex="-1">2. RGW测试套件稳定性问题 <a class="header-anchor" href="#_2-rgw测试套件稳定性问题" aria-label="Permalink to &quot;2. RGW测试套件稳定性问题&quot;">​</a></h3><p><strong>主要问题</strong>：</p><ol><li>DBStore测试失败，需标记已知失败的测试用例。</li><li>Valgrind内存泄漏，影响<code>notifications</code>和<code>multisite</code>测试。</li><li>CLS测试超时，部分测试因非EC集群配置失败。</li></ol><p><strong>后续计划</strong>：</p><ul><li>定期检查Toothology测试结果，更新Bug Tracker。</li><li>每周四召开Bug Scrub会议，协调问题修复优先级。</li></ul><h3 id="_3-rgw主要版本稳定性策略" tabindex="-1">3. RGW主要版本稳定性策略 <a class="header-anchor" href="#_3-rgw主要版本稳定性策略" aria-label="Permalink to &quot;3. RGW主要版本稳定性策略&quot;">​</a></h3><p><strong>核心讨论</strong>：如何定义和确保上游main分支的稳定性？</p><p><strong>当前实践</strong>：</p><ul><li>main分支为“不稳定”分支，允许合并新特性。</li><li>发布稳定分支后，仅接受bugfix。</li><li>依赖RGW测试套件和下游规模化测试。</li></ul><p><strong>改进建议</strong>：</p><ol><li>自动化规模化测试。</li><li>性能基线比对。</li><li>资源协调。</li></ol><p><strong>后续行动</strong>：</p><ul><li>在CSE会议中讨论测试流程优化。</li><li>联系Mark Nelson征询性能测试意见。</li></ul><h3 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h3><ul><li>Adam的Datalog PR，剩余两个PR将优先拆分提交。</li></ul><h3 id="行动计划总结" tabindex="-1">行动计划总结 <a class="header-anchor" href="#行动计划总结" aria-label="Permalink to &quot;行动计划总结&quot;">​</a></h3><p>| 事项 | 负责人 | 时间节点 | ||--|-| | 提交Usage Log Trimming PR | Matthew H | 本周内 | | 标记DBStore测试失败用例 | Adam/Ali | 下周 | | Valgrind问题定位 | 待分配 | 两周内 | | 规模化测试方案讨论 | Casey/Yuri | 下次CSE会议 |</p><p><strong>备注</strong>：保留关键词（如CRUSH, OSD, RADOS, Erasure Coding等）以符合技术上下文。</p>',28)])])}const h=i(l,[["render",r]]);export{c as __pageData,h as default};
